import json,collections
from pathlib import Path
from legal_skill_guard.openexempt import upstream
from legal_skill_guard.learning.experiment import now
root=Path.cwd();run=root/"runs/legal_openexempt_closed_feedback_public_assets128_20261021_run02"
cfg=json.loads((root/"configs/openexempt_closed_feedback_public_assets128_20261021_run02.json").read_text())
records=json.loads((run/"batches/b3_prequential_records.json").read_text())
assert all(len(rs)==32 for rs in records.values())
Eval=upstream("evaluator").Evaluator;Claim=upstream("source.pydantic_response").Claim;ev=Eval([])
roles=("empty","frozen_after_B1","skills")
by={n:{(r["case_id"],r["family"]):r for r in records[n]} for n in roles}
entries=[];percase=[];extra=[];states={n:collections.Counter() for n in roles}
for i in range(213,229):
 target=json.loads((root/cfg["grading_directory"]/f"{i}.json").read_text())["targets"]["EV"]
 casecounts={}
 for n in roles:
  r=by[n][i,"EV"];answer=r["parsed"]["answer"];normalized={k.strip().lower():v for k,v in answer.items()}
  count=collections.Counter();used=set()
  for asset,claims in target.items():
   key=ev._find_matching_asset_description(asset.strip().lower(),list(normalized))
   assert key is None or key not in used
   if key is not None:used.add(key)
   predicted=[Claim(**p) for p in normalized.get(key,[])]
   remaining={Claim(**c).normalized_citation:Claim(**c) for c in claims};tp=0
   for pred in predicted:
    match,rel=ev._find_matching_claim(pred,list(remaining.values()))
    if match and rel<.05:
     remaining.pop(match.normalized_citation);tp+=1
   for c in claims:
    t=Claim(**c);matching=[p for p in predicted if p.normalized_citation==t.normalized_citation]
    correct=any(ev._absolute_relative_error(p.claim_value,t.claim_value)<.05 for p in matching)
    status="correct" if correct else "wrong_amount" if matching else "omitted"
    states[n][status]+=1
    row=next((x for x in entries if (x["case_id"],x["asset"],x["citation"])==(i,asset,t.citation)),None)
    if row is None:
     row={"case_id":i,"asset":asset,"citation":t.citation,"target_value":t.claim_value,"by_role":{}};entries.append(row)
    ec=by[n][i,"EC"]["parsed"]["answer"];eck=ev._find_matching_asset_description(asset.strip().lower(),list(ec))
    eclist=ec.get(eck,[])
    row["by_role"][n]={"status":status,"predicted_values":[p.claim_value for p in matching],
     "citation_in_independent_samebank_EC":any(Claim.normalize_citation(v)==t.normalized_citation for v in eclist)}
   count["tp"]+=tp;count["fp"]+=len(predicted)-tp;count["fn"]+=len(claims)-tp
   targetcit={Claim(**c).normalized_citation for c in claims}
   for pred in predicted:
    if pred.normalized_citation not in targetcit:extra.append({"role":n,"case_id":i,"asset":asset,"prediction":pred.model_dump(),"kind":"citation_not_in_native_target"})
  for k,cs in normalized.items():
   if k not in used:count["fp"]+=len(cs)
  assert all(count[k]==r["score"]["full_output_claim_"+k] for k in ("tp","fp","fn"))
  casecounts[n]=dict(count)
 percase.append({"case_id":i,"counts":casecounts})
transitions={}
for ref in ("empty","frozen_after_B1"):
 transitions[ref]=dict(collections.Counter(x["by_role"][ref]["status"]+"->"+x["by_role"]["skills"]["status"] for x in entries))
changed=[x for x in entries if x["by_role"]["frozen_after_B1"]!=x["by_role"]["skills"]]
changed_native_scores=[]
for f in ("EC","EV"):
 for i in range(213,229):
  a,b=by["frozen_after_B1"][i,f],by["skills"][i,f]
  if a["parsed"]!=b["parsed"] or a["score"]!=b["score"]:
   changed_native_scores.append({"case_id":i,"family":f,"parent_score":a["score"],"online_score":b["score"],
    "parent_answer":a["parsed"],"online_answer":b["parsed"]})
out={"at":now(),"classification":"All B3 native EV target and false-positive decomposition; TRAIN first-forecast, no new inference or TEST",
"source_cases":16,"target_claim_count":len(entries),"statuses":{n:dict(v) for n,v in states.items()},
"all16_original_full_output_count_checks":percase,"all_native_target_claims":entries,"status_transitions":transitions,
"changed_current_vs_own_B1_claim_records":changed,"all_extra_citations":extra,"all_different_current_vs_ownB1_answers":changed_native_scores,
"all_remaining_online_native_errors":[x for x in entries if x["by_role"]["skills"]["status"]!="correct"],
"native_scorer_and_tolerance_unchanged":True,"EC_is_independent_request_not_EV_intermediate":True,
"new_model_or_teacher_calls":0,"no_TEST_semantics_loaded":True}
print(json.dumps(out,ensure_ascii=False))
